        }
        if ($operator === 'BETWEEN' && is_array($value) && count($value) === 2) {
            [$lower, $upper] = array_values($value);
            $lowerRowid = self::rowidConstraintIntValue133($lower);
            $upperRowid = self::rowidConstraintIntValue133($upper);
