    {
        $parts = [];
        foreach ($constraintUsage as $usage) {
            if (!($usage['usable'] ?? false)) {
                continue;
            }
            $parts[] = ($usage['omit'] ? 'omit' : 'residual')
                . ':' . (string) $usage['column']
                . ':' . (string) $usage['operator'];
        }

        return implode('|', $parts);
    }

