                    : null,
                '>' => ['lower' => (int) $value, 'upper' => null, 'lowerInclusive' => false, 'upperInclusive' => true],
                '>=' => ['lower' => (int) $value, 'upper' => null, 'lowerInclusive' => true, 'upperInclusive' => true],
