        if (($current['nullExtended'] ?? false) !== ($next['nullExtended'] ?? false)) {
            return 'lateral-hidden-null-extension-changed';
        }
        if (($current['hiddenResidualColumns'] ?? []) !== ($next['hiddenResidualColumns'] ?? [])) {
